// api/create-checkout-session.js
// Creates a Stripe Hosted Checkout session from a cart of { handle, size, quantity }.
// The server is the source of truth for price — it looks up the Stripe Price ID
// for each product handle in data/stripe-products.json (generated by scripts/stripe-sync.js).

import Stripe from 'stripe';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { ZONES, resolveZone } from '../config/shipping.js';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const MAPPING_PATH = path.resolve(__dirname, '..', 'data', 'stripe-products.json');

let productMap = null;
function loadProductMap() {
  if (productMap) return productMap;
  const raw = fs.readFileSync(MAPPING_PATH, 'utf8');
  productMap = JSON.parse(raw);
  return productMap;
}

export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', 'https://protonlab.cc');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    return res.status(200).end();
  }

  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { items, customerEmail, customerName, shippingRegion, fbp, fbc, gaClientId, gaSessionId } = req.body;

  // Meta ads attribution — the browser's _fbp/_fbc cookies arrive in the body;
  // IP and user-agent are read from this request (it comes from the customer's
  // browser, unlike the Stripe webhook later). All four are stamped onto the
  // PaymentIntent metadata so the webhook can send a fully-attributed
  // Conversions API Purchase event.
  const clientIp =
    (typeof req.headers['x-forwarded-for'] === 'string' && req.headers['x-forwarded-for'].split(',')[0].trim()) || '';
  const clientUa = (req.headers['user-agent'] || '').slice(0, 480);

  // items = [{ handle: 'ss-race-jersey', size: 'M', quantity: 1, image?: '...' }]
  // shippingRegion = 'uk' | 'europe' | 'world' — omitted by older frontends, defaults to 'uk'
  const region = resolveZone(shippingRegion);
  const zone = ZONES[region];

  if (!Array.isArray(items) || items.length === 0) {
    return res.status(400).json({ error: 'No items provided' });
  }

  let map;
  try {
    map = loadProductMap();
  } catch (err) {
    console.error('Failed to load product mapping:', err);
    return res.status(500).json({ error: 'Product catalog unavailable' });
  }

  // First pass: validate items and look up map entries.
  const looked = [];
  for (const item of items) {
    if (!item || typeof item.handle !== 'string' || typeof item.size !== 'string') {
      return res.status(400).json({ error: 'Invalid cart item' });
    }
    const entry = map[item.handle];
    if (!entry || !entry.priceId) {
      return res.status(400).json({ error: `Unknown product: ${item.handle}` });
    }
    const quantity = Number.isFinite(item.quantity) && item.quantity > 0 ? Math.floor(item.quantity) : 1;
    const clubHandle = typeof item.clubHandle === 'string' ? item.clubHandle : undefined;
    // Club shops keep the price agreed when the shop opened. Overrides live in
    // the server-side map (baked in by stripe-sync from data/club-prices.json),
    // so the client can only ever select a price we created for that club.
    const override = entry.clubPrices && clubHandle ? entry.clubPrices[clubHandle] : undefined;
    looked.push({ item, entry, quantity, clubHandle, override });
  }

  // The charged currency is derived from the delivery zone — never from the
  // client (any client-sent currency field is ignored). A Stripe session is
  // single-currency, so EUR is all-or-nothing: if any line can't be priced in
  // EUR (no EUR price, or a club item — club prices are GBP agreements) the
  // whole session falls back to GBP.
  const sessionCurrency =
    zone.currency === 'eur' && looked.every(l => l.entry.eur && !l.override)
      ? 'eur'
      : 'gbp';

  const resolved = looked.map(({ item, entry, quantity, clubHandle, override }) => {
    const eur = sessionCurrency === 'eur' ? entry.eur : undefined;
    return {
      handle: item.handle,
      size: item.size,
      quantity,
      priceId: override ? override.priceId : eur ? eur.priceId : entry.priceId,
      name: entry.name,
      unitAmount: override ? override.unitAmount : eur ? eur.unitAmount : entry.unitAmount,
      image: typeof item.image === 'string' ? item.image : undefined,
      clubName: typeof item.clubName === 'string' ? item.clubName : undefined,
      clubHandle,
    };
  });

  // Pre-discount subtotal in minor units of the session currency — decides
  // free-shipping eligibility. Uses the server-side price map, so the client
  // can't influence it.
  const subtotal = resolved.reduce((sum, i) => sum + (i.unitAmount || 0) * i.quantity, 0);

  // Club name(s) for this order — usually one club per cart. Deduped + joined
  // so it survives into the order emails via payment_intent metadata.
  const club = [...new Set(resolved.map(i => i.clubName).filter(Boolean))].join(', ');

  // Club handle(s) — machine key for the price override, kept separate from the
  // display name above ('protonlab' is the retail sentinel, not a club).
  const clubHandleMeta = [...new Set(
    resolved.map(i => i.clubHandle).filter(h => h && h !== 'protonlab')
  )].join(', ');

  try {
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      mode: 'payment',

      customer_email: customerEmail || undefined,

      // Collect a delivery address on the hosted page. Stripe copies this onto
      // the resulting PaymentIntent's `shipping` field, which the webhook reads.
      // Countries are restricted to the zone the customer picked in the cart,
      // so the shipping price always matches the destination.
      shipping_address_collection: {
        allowed_countries: zone.allowedCountries,
      },
      // Phone is required at checkout so we can reach the customer about their order.
      phone_number_collection: { enabled: true },

      // Rates come from config/shipping.js — UK & Ireland get free standard
      // delivery at/over the threshold, next-day stays paid either way.
      shipping_options: zone.optionsFor(subtotal, sessionCurrency),

      // Customers can enter discount codes (created in the Stripe dashboard
      // under Product catalogue → Coupons) on the hosted page.
      allow_promotion_codes: true,

      // Marketing consent checkbox on the hosted page ('auto' shows it where
      // Stripe supports promotional consent for the customer's locale). The
      // webhook only adds buyers to the mailing list when this comes back
      // 'opt_in' — absent/opt_out means no list add, order emails unaffected.
      consent_collection: { promotions: 'auto' },

      line_items: resolved.map((item) => ({
        price: item.priceId,
        quantity: item.quantity,
      })),

      // Stripe Checkout doesn't allow per-line-item descriptions when using a
      // Price ID, so surface size info via custom_text so the customer sees it
      // on the hosted page. Fulfillment still uses metadata.items (authoritative).
      custom_text: {
        shipping_address: {
          message: zone.customText(subtotal, sessionCurrency),
        },
        submit: {
          message: 'Sizes: ' + resolved.map(i => `${i.name} — ${i.size}`).join(', '),
        },
      },

      payment_intent_data: {
        metadata: {
          name: customerName || '',
          email: customerEmail || '',
          club,
          club_handle: clubHandleMeta,
          shipping_region: region,
          currency: sessionCurrency,
          subtotal: String(subtotal),
          product: resolved.map(i => i.name).join(', '),
          items: JSON.stringify(
            resolved.map(i => ({ name: i.name, handle: i.handle, size: i.size, qty: i.quantity }))
          ),
          fbp: typeof fbp === 'string' ? fbp.slice(0, 100) : '',
          fbc: typeof fbc === 'string' ? fbc.slice(0, 500) : '',
          client_ip: clientIp,
          client_ua: clientUa,
          // GA4 browser identity (_ga / _ga_* cookies) — lets the webhook's
          // Measurement Protocol purchase share the buyer's client_id and
          // session, so GA4 dedups it against the /success page event.
          ga_client_id: typeof gaClientId === 'string' ? gaClientId.slice(0, 100) : '',
          ga_session_id: typeof gaSessionId === 'string' ? gaSessionId.slice(0, 100) : '',
        },
      },

      success_url: `${process.env.SITE_URL}/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${process.env.SITE_URL}/cancel`,
    });

    res.status(200).json({ url: session.url });
  } catch (err) {
    console.error('Stripe session creation error:', err);
    res.status(500).json({ error: 'Failed to create checkout session' });
  }
}
